// Decimal ↔ binary with explicit place-value breakdown
function toBinary(n) { return n.toString(2); }

function fromBinary(bits) {
  let value = 0;
  for (let i = 0; i < bits.length; i++) {
    const bit = Number(bits[bits.length - 1 - i]); // rightmost = 2^0
    value += bit * (2 ** i);
  }
  return value;
}

console.log(toBinary(13));        // "1101"
console.log(fromBinary('1101'));  // 13
console.log(toBinary(255));       // "11111111" (max byte)
console.log(2 ** 8);              // 256 values in a byte

// Core identities every developer should know
const BITS_PER_BYTE = 8;
const VALUES_IN_BYTE = 2 ** BITS_PER_BYTE; // 256
const MAX_BYTE_VALUE  = VALUES_IN_BYTE - 1; // 255  ← common off-by-one trap

// n bits → 2^n distinct values; each extra bit DOUBLES the range
const distinctValues = (n) => 2 ** n;

// 4 bits = 1 hex digit (nibble) — hex is just compact binary
const BITS_PER_HEX_DIGIT = 4; // 2^4 = 16 hex symbols (0-F)
